class CommandListEditor final:public QWidget{
public:
    CommandListEditor(QWidget *parent):QWidget(parent){
        auto *layout=new QVBoxLayout(this);layout->setContentsMargins(0,0,0,0);m_list=new QListWidget(this);m_list->setObjectName("commandList");layout->addWidget(m_list,1);
        auto *row=new QHBoxLayout;layout->addLayout(row);m_choices=new QComboBox(this);m_choices->setMinimumContentsLength(14);m_choices->setSizeAdjustPolicy(QComboBox::AdjustToMinimumContentsLengthWithIcon);row->addWidget(m_choices,1);
        auto *add=new QPushButton(tr("Adicionar"),this);row->addWidget(add);connect(add,&QPushButton::clicked,this,[this]{const auto id=m_choices->currentData().toString();if(m_list->count()>=128||(id!="-"&&ids().contains(id)))return;auto *item=new QListWidgetItem(m_choices->currentText(),m_list);item->setData(Qt::UserRole,id);m_list->setCurrentItem(item);if(changed)changed();});
        auto *buttons=new QHBoxLayout;layout->addLayout(buttons);for(int direction:{-1,1,0}){auto *b=new QPushButton(direction==-1?tr("Subir"):direction==1?tr("Descer"):tr("Remover"),this);buttons->addWidget(b);connect(b,&QPushButton::clicked,this,[this,direction]{int row=m_list->currentRow();if(row<0)return;if(!direction)delete m_list->takeItem(row);else{if(row+direction<0||row+direction>=m_list->count())return;auto *item=m_list->takeItem(row);m_list->insertItem(row+direction,item);m_list->setCurrentRow(row+direction);}if(changed)changed();});}
    }
    QStringList ids()const{QStringList ids;for(int i=0;i<m_list->count();++i)ids.append(m_list->item(i)->data(Qt::UserRole).toString());return ids;}
    void setChoices(const QVector<EditorCommand>&commands){m_commands=commands;m_choices->clear();m_choices->addItem(tr("Separador"),"-");for(const auto&c:commands)m_choices->addItem(c.label,c.id);setIds(ids());}
    void setIds(const QStringList&ids){m_list->clear();for(const auto&id:ids){QString label=id=="-"?tr("──────── Separador"):id;for(const auto&c:m_commands)if(c.id==id)label=c.label;auto *item=new QListWidgetItem(label,m_list);item->setData(Qt::UserRole,id);}}
    std::function<void()> changed;
private:QListWidget*m_list;QComboBox*m_choices;QVector<EditorCommand>m_commands;
};

