    const QStringList labels{tr("Lista de arquivos"),tr("Árvores de pastas"),tr("Menus"),tr("Barras"),tr("Abas"),tr("Visualizador")};const auto ids=interfaceComponentIds();for(int i=0;i<ids.size();++i)m_component->addItem(labels[i],ids[i]);
    auto *colorForm=new QFormLayout;colors->addLayout(colorForm);auto line=[&](const QString &label){auto *row=new QWidget(this);auto *layout=new QHBoxLayout(row);layout->setContentsMargins(0,0,0,0);auto *input=new QLineEdit(row);input->setMaxLength(7);input->setPlaceholderText(tr("Herdar do tema"));auto *choose=new QPushButton(tr("Escolher…"),row);auto *reset=new QPushButton(tr("Herdar"),row);layout->addWidget(input,1);layout->addWidget(choose);layout->addWidget(reset);connect(choose,&QPushButton::clicked,this,[this,input]{const auto color=QColorDialog::getColor(QColor(input->text()),this,tr("Cor do componente"));if(color.isValid()){input->setText(color.name());storeComponent();}});connect(reset,&QPushButton::clicked,this,[this,input]{input->clear();storeComponent();});connect(input,&QLineEdit::textEdited,this,[this]{storeComponent();});colorForm->addRow(label,row);return input;};
