    connect(chooseLanguage,&QPushButton::clicked,this,[this,languagePath]{const auto path=QFileDialog::getOpenFileName(this,tr("Idioma da interface"),{},tr("Tradução Qt (*.qm)"));if(!path.isEmpty()){m_value.languageFile=path;languagePath->setText(path);}});connect(resetLanguage,&QPushButton::clicked,this,[this,languagePath]{m_value.languageFile.clear();languagePath->clear();});
    auto *icons=page(tr("Ícones"),tr("Escolha ícones PNG/ICO/JPEG locais para comandos. Arquivo ausente ou inválido mantém o ícone padrão; não são carregados SVG ou arquivos remotos."));auto *iconTable=new QTableWidget(this);iconTable->setObjectName("studioIcons");iconTable->setColumnCount(2);iconTable->setHorizontalHeaderLabels({tr("Comando"),tr("Arquivo de ícone")});iconTable->horizontalHeader()->setSectionResizeMode(0,QHeaderView::Stretch);iconTable->horizontalHeader()->setSectionResizeMode(1,QHeaderView::Stretch);icons->addWidget(iconTable,1);
    auto refreshIcons=[this,iconTable]{iconTable->setRowCount(0);for(const auto &c:m_commands){int r=iconTable->rowCount();iconTable->insertRow(r);auto *item=new QTableWidgetItem(c.label);item->setData(Qt::UserRole,c.id);item->setFlags(item->flags()&~Qt::ItemIsEditable);iconTable->setItem(r,0,item);auto *path=new QTableWidgetItem(m_value.icons.value(c.id));path->setFlags(path->flags()&~Qt::ItemIsEditable);iconTable->setItem(r,1,path);}};refreshIcons();
    auto *iconButtons=new QHBoxLayout;icons->addLayout(iconButtons);auto *chooseIcon=new QPushButton(tr("Escolher ícone…"),this),*resetIcon=new QPushButton(tr("Restaurar ícone"),this);iconButtons->addWidget(chooseIcon);iconButtons->addWidget(resetIcon);
    connect(chooseIcon,&QPushButton::clicked,this,[this,iconTable]{int row=iconTable->currentRow();if(row<0)return;const auto path=QFileDialog::getOpenFileName(this,tr("Ícone do comando"),{},tr("Ícones (*.png *.ico *.jpg *.jpeg)"));if(path.isEmpty())return;m_value.icons[iconTable->item(row,0)->data(Qt::UserRole).toString()]=path;iconTable->item(row,1)->setText(path);});connect(resetIcon,&QPushButton::clicked,this,[this,iconTable]{int row=iconTable->currentRow();if(row<0)return;m_value.icons.remove(iconTable->item(row,0)->data(Qt::UserRole).toString());iconTable->item(row,1)->setText({});});
    auto *launchers=page(tr("Lançadores"),tr("Crie comandos para programas instalados. A execução terá prévia e confirmação; o programa externo controla alterações e resultado. Argumentos: um por linha. Use {file}, {folder} ou {selection} como argumento inteiro."));auto *launcherBody=new QHBoxLayout;launchers->addLayout(launcherBody,1);m_launchers=new QListWidget(this);m_launchers->setObjectName("studioLaunchers");launcherBody->addWidget(m_launchers,1);auto *launcherForm=new QFormLayout;launcherBody->addLayout(launcherForm,2);
    m_launcherName=new QLineEdit(this);m_launcherName->setMaxLength(128);m_launcherName->setObjectName("launcherName");launcherForm->addRow(tr("Nome"),m_launcherName);auto *programRow=new QWidget(this);auto *programLayout=new QHBoxLayout(programRow);programLayout->setContentsMargins(0,0,0,0);m_program=new QLineEdit(this);m_program->setObjectName("launcherProgram");m_program->setMaxLength(32768);auto *browse=new QPushButton(tr("Escolher…"),this);programLayout->addWidget(m_program);programLayout->addWidget(browse);launcherForm->addRow(tr("Programa"),programRow);m_arguments=new QPlainTextEdit(this);m_arguments->setObjectName("launcherArguments");launcherForm->addRow(tr("Argumentos"),m_arguments);
    auto *launcherButtons=new QHBoxLayout;launchers->addLayout(launcherButtons);auto *saveLauncher=new QPushButton(tr("Guardar comando"),this),*newLauncher=new QPushButton(tr("Novo comando"),this),*removeLauncher=new QPushButton(tr("Remover comando"),this);saveLauncher->setObjectName("saveLauncher");newLauncher->setObjectName("newLauncher");for(auto*b:{saveLauncher,newLauncher,removeLauncher})launcherButtons->addWidget(b);
    auto refreshLaunchers=[this]{m_launchers->clear();for(const auto&c:m_value.launchers)m_launchers->addItem(c.name);};refreshLaunchers();
    connect(browse,&QPushButton::clicked,this,[this]{const auto path=QFileDialog::getOpenFileName(this,tr("Programa do lançador"),{},tr("Programas (*.exe)"));if(!path.isEmpty())m_program->setText(path);});
