void InterfaceStudio::refreshCommands(){
    m_commands.erase(std::remove_if(m_commands.begin(),m_commands.end(),[](const EditorCommand&c){return c.id.startsWith("user.");}),m_commands.end());for(const auto &c:m_value.launchers)m_commands.append({"user."+c.id,tr("Lançar: %1").arg(c.name)});m_barCommands->setChoices(m_commands);loadMenu();
}
void InterfaceStudio::loadBar(){if(m_loading)return;QScopedValueRollback<bool>guard(m_loading,true);const int i=m_bars->currentIndex();const bool valid=i>=0&&i<m_value.toolbars.size();for(auto*w:QList<QWidget*>{m_barName,m_barVisible,m_barMovable,m_barCommands})w->setEnabled(valid);if(!valid){m_barName->clear();m_barCommands->setIds({});return;}const auto&v=m_value.toolbars[i];m_barName->setText(v.name);m_barVisible->setChecked(v.visible);m_barMovable->setChecked(v.movable);m_barCommands->setIds(v.commands);}
void InterfaceStudio::storeBar(){if(m_loading)return;const int i=m_bars->currentIndex();if(i<0||i>=m_value.toolbars.size())return;auto &v=m_value.toolbars[i];v.name=m_barName->text();v.visible=m_barVisible->isChecked();v.movable=m_barMovable->isChecked();v.commands=m_barCommands->ids();m_bars->setItemText(i,v.name);}
void InterfaceStudio::loadMenu(){if(m_loading)return;QScopedValueRollback<bool>guard(m_loading,true);const int i=m_menu->currentIndex();if(i<0)return;const auto &spec=m_menus[i];const auto &map=spec.context?m_value.contexts:m_value.menus;m_customMenu->setChecked(map.contains(spec.id));m_menuCommands->setChoices(spec.choices.isEmpty()?m_commands:spec.choices);m_menuCommands->setIds(map.value(spec.id,spec.defaults));m_menuCommands->setEnabled(m_customMenu->isChecked());}
void InterfaceStudio::storeMenu(){if(m_loading)return;const int i=m_menu->currentIndex();if(i<0)return;const auto &spec=m_menus[i];auto &map=spec.context?m_value.contexts:m_value.menus;if(m_customMenu->isChecked())map[spec.id]=m_menuCommands->ids();else map.remove(spec.id);}
void InterfaceStudio::loadComponent(){if(m_loading)return;QScopedValueRollback<bool>guard(m_loading,true);const auto v=m_value.components.value(m_component->currentData().toString());m_background->setText(v.background);m_foreground->setText(v.foreground);m_customFont->setChecked(v.fontSize!=0);m_fontSize->setValue(v.fontSize?v.fontSize:9);m_fontSize->setEnabled(v.fontSize!=0);}
void InterfaceStudio::storeComponent(){if(m_loading)return;const auto id=m_component->currentData().toString();ComponentAppearance v{m_background->text(),m_foreground->text(),m_customFont->isChecked()?m_fontSize->value():0};if(v.background.isEmpty()&&v.foreground.isEmpty()&&!v.fontSize)m_value.components.remove(id);else m_value.components[id]=v;}
